{
  "type": "演化时间线信息图",
  "instruction": "以 REFERENCE_0 为结构基础，把平面矢量设计转成高度写实 3D 信息图。把平滑坡道换成一块块独立石阶，把所有生物升级为照片级写实 3D 模型。",
  "style": {
    "background": "{argument name=\"background style\" default=\"复古纹理羊皮纸\"}",
    "staircase": "{argument name=\"staircase material\" default=\"写实纹理石块\"}",
    "subjects": "{argument name=\"organism style\" default=\"高细节照片级写实 3D 渲染\"}"
  },
  "layout": {
    "main_title": "{argument name=\"main title\" default=\"人类演化\"}",
    "sections": [
      {
        "position": "左侧栏",
        "count": 8,
        "labels": ["L0: 单细胞生命", "L1: 多细胞生物", "L2: 动物界", "L3: 脊索动物", "L4: 上陆革命", "L5: 哺乳纲", "L6: 人科演化", "L7: 智人纪元"]
      },
      {
        "position": "右上",
        "title": "获得的功能 / 失去的功能",
        "description": "带加号和减号图标的图例"
      },
      {
        "position": "底部居中",
        "title": "演化关键里程碑",
        "count": 6,
        "description": "时间线配 6 个人形剪影，展现从猿到人的演化"
      }
    ],
    "centerpiece": {
      "description": "蜿蜒石阶，共 25 级编号台阶，每级放置特定生物。",
      "count": 25,
      "notable_elements": [
        "第 07 级：水母",
        "第 09 级：菊石",
        "第 10 级：三叶虫",
        "第 24 级：行走的人类",
        "第 25 级：{argument name=\"future evolution concept\" default=\"带问号的发光宇宙剪影\"}"
      ]
    }
  }
}

